package uz.onecall.agent.core

import android.content.ContentUris
import android.content.Context
import android.os.Build
import android.os.Environment
import android.provider.MediaStore
import android.util.Log
import java.io.File

object SamsungRecordingFinder {
    private const val TAG = "SamsungRecordingFinder"

    /**
     * Scan Samsung and Android native call recording folders and MediaStore
     * for high-fidelity two-way call recordings generated by Samsung native dialer.
     * Uses ContentResolver to safely read across Scoped Storage in Android 13-15.
     */
    fun findLatestNativeCallRecording(
        context: Context,
        phoneNumber: String,
        callStartTime: Long,
        callEndedTime: Long
    ): File? {
        val cleanPhone = phoneNumber.replace(Regex("[^0-9]"), "")
        val lastDigits = if (cleanPhone.length >= 7) cleanPhone.takeLast(7) else cleanPhone

        // Method 1: Check MediaStore Audio (Official Android 11-15 Scoped Storage API)
        val mediaStoreResult = findViaMediaStore(context, lastDigits, callStartTime, callEndedTime)
        if (mediaStoreResult != null && mediaStoreResult.exists() && mediaStoreResult.length() > 0) {
            return mediaStoreResult
        }

        // Method 2: Direct File System Access (Common Samsung paths)
        val directDirs = listOf(
            File("/storage/emulated/0/Recordings/Call"),
            File("/storage/emulated/0/Recordings"),
            File(Environment.getExternalStorageDirectory(), "Recordings/Call"),
            File(Environment.getExternalStorageDirectory(), "Recordings"),
            File(Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_RECORDINGS), "Call"),
            File(Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_RECORDINGS), ""),
            File(Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_MUSIC), "Recordings/Call")
        )

        for (dir in directDirs) {
            try {
                if (dir.exists() && dir.isDirectory) {
                    val files = dir.listFiles { file ->
                        file.isFile && (file.extension.equals("m4a", true) || 
                                        file.extension.equals("amr", true) || 
                                        file.extension.equals("mp3", true) ||
                                        file.extension.equals("wav", true))
                    } ?: emptyArray()

                    val sorted = files.sortedByDescending { it.lastModified() }
                    for (f in sorted) {
                        val modTime = f.lastModified()
                        val diffMs = Math.abs(modTime - callEndedTime)
                        val fileName = f.name
                        val matchesPhone = lastDigits.isNotBlank() && fileName.replace(Regex("[^0-9]"), "").contains(lastDigits)

                        // File modified within 120 seconds of call end OR matches the dialed/received phone number
                        if (matchesPhone || (diffMs < 120000 && modTime >= callStartTime - 15000)) {
                            Log.i(TAG, "Found Samsung native recording file directly: ${f.absolutePath} (${f.length()} bytes)")
                            return f
                        }
                    }
                }
            } catch (e: Exception) {
                Log.w(TAG, "Could not read direct dir ${dir.absolutePath}: ${e.message}")
            }
        }

        return null
    }

    private fun findViaMediaStore(
        context: Context,
        lastDigits: String,
        callStartTime: Long,
        callEndedTime: Long
    ): File? {
        try {
            val projection = arrayOf(
                MediaStore.Audio.Media._ID,
                MediaStore.Audio.Media.DISPLAY_NAME,
                MediaStore.Audio.Media.DATE_MODIFIED,
                MediaStore.Audio.Media.SIZE
            )

            val cursor = context.contentResolver.query(
                MediaStore.Audio.Media.EXTERNAL_CONTENT_URI,
                projection,
                null,
                null,
                "${MediaStore.Audio.Media.DATE_MODIFIED} DESC"
            )

            cursor?.use {
                var count = 0
                while (it.moveToNext() && count < 40) {
                    count++
                    val id = it.getLong(it.getColumnIndexOrThrow(MediaStore.Audio.Media._ID))
                    val name = it.getString(it.getColumnIndexOrThrow(MediaStore.Audio.Media.DISPLAY_NAME)) ?: ""
                    val modSec = it.getLong(it.getColumnIndexOrThrow(MediaStore.Audio.Media.DATE_MODIFIED))
                    val modMs = modSec * 1000
                    val size = it.getLong(it.getColumnIndexOrThrow(MediaStore.Audio.Media.SIZE))

                    if (size <= 0) continue

                    val diffMs = Math.abs(modMs - callEndedTime)
                    val matchesPhone = lastDigits.isNotBlank() && name.replace(Regex("[^0-9]"), "").contains(lastDigits)
                    val isCallFile = name.contains("Call", ignoreCase = true) || 
                                     name.contains("Qo'ng'iroq", ignoreCase = true) ||
                                     name.contains("Вызов", ignoreCase = true) ||
                                     name.contains("통화", ignoreCase = true) ||
                                     name.contains("Record", ignoreCase = true)

                    if (matchesPhone || (isCallFile && diffMs < 120000 && modMs >= callStartTime - 15000)) {
                        val contentUri = ContentUris.withAppendedId(MediaStore.Audio.Media.EXTERNAL_CONTENT_URI, id)
                        Log.i(TAG, "Found candidate in MediaStore: $name (id=$id, size=$size, diff=${diffMs}ms). Copying stream...")

                        try {
                            val cacheDir = File(context.filesDir, "samsung_records").apply { mkdirs() }
                            val ext = if (name.endsWith(".amr", ignoreCase = true)) "amr" else "m4a"
                            val dest = File(cacheDir, "samsung_${System.currentTimeMillis()}.$ext")
                            
                            context.contentResolver.openInputStream(contentUri)?.use { input ->
                                dest.outputStream().use { output ->
                                    input.copyTo(output)
                                }
                            }

                            if (dest.exists() && dest.length() > 0) {
                                Log.i(TAG, "Successfully copied native Samsung recording to cache: ${dest.absolutePath} (${dest.length()} bytes)")
                                return dest
                            }
                        } catch (e: Exception) {
                            Log.e(TAG, "Failed copying stream from MediaStore: ${e.message}")
                        }
                    }
                }
            }
        } catch (e: Exception) {
            Log.w(TAG, "Error querying MediaStore: ${e.message}")
        }
        return null
    }
}
